def process_adjacency_matrix():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    N = int(data[0])
    for i in range(1, N + 1):
        A = list(map(int, data[i].split()))
        connected_vertices = []
        for j in range(N):
            if A[j] == 1:
                connected_vertices.append(j + 1)
        print(" ".join(map(str, connected_vertices)))
